from target import cache_key


def test_key_shape():
    assert cache_key("u", "/a", 10) == ("u", "/a")


def test_latency_does_not_change_key():
    assert cache_key("u", "/a", 10) == cache_key("u", "/a", 99)


def test_zero_latency():
    assert cache_key("u", "/a", 0) == ("u", "/a")
